{"implementation": "def solve(case):
    payload = case.get("payload", case)
    segments = payload["segments"]
    budget = payload["budget"]
    required = ("name", "importance", "minimum", "capacity")
    for i, seg in enumerate(segments):
        for field in required:
            if field not in seg:
                raise ValueError(f"Segment {i} missing required field '{field}'")
    allocs = [int(seg["minimum"]) for seg in segments]
    quota_sum = sum(allocs)
    cap_sum = sum(int(seg["capacity"]) for seg in segments)
    if budget < quota_sum:
        raise ValueError(f"Budget {budget} is below minimum quota sum {quota_sum}")
    if budget > cap_sum:
        raise ValueError(f"Budget {budget} exceeds total capacity {cap_sum}")
    remaining = budget - quota_sum
    while remaining > 0:
        best_idx = -1
        best_priority = -1.0
        for i, seg in enumerate(segments):
            if allocs[i] >= int(seg["capacity"]):
                continue
            priority = seg["importance"] / (allocs[i] + 1)
            if priority > best_priority:
                best_priority = priority
                best_idx = i
        if best_idx == -1:
            break
        allocs[best_idx] += 1
        remaining -= 1
    allocations = {seg["name"]: allocs[i] for i, seg in enumerate(segments)}
    name_mapping = {str(i): seg["name"] for i, seg in enumerate(segments)}
    total = sum(allocs)
    return {"allocations": allocations, "name_mapping": name_mapping, "total": total}"}
